-- Save MJ: Queries (core SP call only)
DO $mj$
DECLARE
  p_Name_54e751c846df VARCHAR(255);
  p_CategoryID_54e751c846df UUID;
  p_UserQuestion_54e751c846df TEXT;
  p_Description_54e751c846df TEXT;
  p_SQL_54e751c846df TEXT;
  p_TechnicalDescription_54e751c846df TEXT;
  p_OriginalSQL_54e751c846df TEXT;
  p_Feedback_54e751c846df TEXT;
  p_Status_54e751c846df VARCHAR(15);
  p_QualityRank_54e751c846df INTEGER;
  p_ExecutionCostRank_54e751c846df INTEGER;
  p_UsesTemplate_54e751c846df BOOLEAN;
  p_AuditQueryRuns_54e751c846df BOOLEAN;
  p_CacheEnabled_54e751c846df BOOLEAN;
  p_CacheTTLMinutes_54e751c846df INTEGER;
  p_CacheMaxSize_54e751c846df INTEGER;
  p_EmbeddingVector_54e751c846df TEXT;
  p_EmbeddingModelID_54e751c846df UUID;
  p_CacheValidationSQL_54e751c846df TEXT;
  p_SQLDialectID_54e751c846df UUID;
  p_Reusable_54e751c846df BOOLEAN;
  p_ExternalDataSourceID_54e751c846df UUID;
  p_IsMaterialized_54e751c846df BOOLEAN;
  p_ID_54e751c846df UUID;
BEGIN
  p_Name_54e751c846df := 'Sales: Deal Type Mix';
  p_CategoryID_54e751c846df := '5A1E5000-0000-4000-A000-000000000001';
  p_UserQuestion_54e751c846df := 'How is our business split between new, renewal and expansion motions?';
  p_Description_54e751c846df := 'Deals and amounts by deal type.';
  p_SQL_54e751c846df := '-- New vs renewal vs expansion mix. Master plan §9.3, measure 10 — via the DealType dimension (§9.2).
--
-- THE MIX IS READ FROM THE TYPE TABLE, NOT FROM TYPE NAMES. §9.3 phrases this measure as "new vs
-- renewal vs expansion", which are the labels the seeded rows happen to carry — but nothing here
-- compares them. Rows group by `DealTypeID` and render `DealType.Name` for display only, so a
-- deployment that adds a fourth motion, or renames "Expansion" to "Upsell", gets a correct extra row
-- rather than a silently miscounted one.
--
-- `RequiresRenewalSource` IS THE ONE FLAG THIS QUERY BRANCHES ON, and it is the same flag
-- `CloseDealOperation` uses to decide whether a close takes the renewal door. Reporting it here means
-- the mix and the routing agree by construction: a type the engine treats as a renewal is a type this
-- report counts as one.
--
-- DATE DIMENSION: ActualCloseDate for closed deals, ExpectedCloseDate for open ones — the mix
-- question is "what are we selling in this period", and an open deal belongs to the period it is
-- expected to land in. Both are reported separately below so the two are never silently added.
--
-- PIPELINES FLAGGED OUT OF THE FORECAST LOSE THEIR OPEN DEALS, AS IN PIPELINE SUMMARY AND THE
-- DASHBOARD. Pipeline.IncludeInForecast = 0 marks a pipeline that holds historical deals; its open
-- rows are not the current book, so counting them here made OpenCount and OpenAmount disagree with
-- every other forecast query. Its won and lost deals stay. Naming the pipeline in PipelineID includes it.
SELECT
    d.DealTypeID,
    dt.Name                                     AS DealTypeName,
    dt.RequiresRenewalSource,
    d.CompanyID,
    d.Company                                   AS CompanyName,
    d.PipelineID,
    d.Pipeline                                  AS PipelineName,
    SUM(CASE WHEN st.IsWon = 1 THEN 1 ELSE 0 END)                    AS WonCount,
    SUM(CASE WHEN st.IsWon = 1 THEN ISNULL(d.Amount, 0) ELSE 0 END)  AS WonAmount,
    SUM(CASE WHEN st.IsOpen = 1 THEN 1 ELSE 0 END)                   AS OpenCount,
    SUM(CASE WHEN st.IsOpen = 1 THEN ISNULL(d.Amount, 0) ELSE 0 END) AS OpenAmount,
    SUM(CASE WHEN st.IsLost = 1 THEN 1 ELSE 0 END)                   AS LostCount,
    -- A renewal deal that names no source contract is a data gap worth seeing rather than a row to
    -- filter out: it means the routing had nothing to renew against.
    SUM(CASE WHEN dt.RequiresRenewalSource = 1 AND d.RenewsContractID IS NULL THEN 1 ELSE 0 END)
                                                AS RenewalsMissingSource
FROM [__mj_BizAppsSales].vwDeals d
INNER JOIN [__mj_BizAppsSales].DealStatusType st
        ON st.ID = d.DealStatusTypeID
INNER JOIN [__mj_BizAppsSales].DealType dt
        ON dt.ID = d.DealTypeID
INNER JOIN [__mj_BizAppsSales].Pipeline p
        ON p.ID = d.PipelineID
WHERE 1 = 1
  {% if CompanyID %}
  AND d.CompanyID = {{ CompanyID | sqlString }}
  {% endif %}
  {% if PipelineID %}
  AND d.PipelineID = {{ PipelineID | sqlString }}
  {% else %}
  AND (st.IsOpen = 0 OR p.IncludeInForecast = 1)
  {% endif %}
  {% if PeriodStart %}
  AND COALESCE(d.ActualCloseDate, d.ExpectedCloseDate) >= {{ PeriodStart | sqlString }}
  {% endif %}
  {% if PeriodEnd %}
  AND COALESCE(d.ActualCloseDate, d.ExpectedCloseDate) <= {{ PeriodEnd | sqlString }}
  {% endif %}
GROUP BY
    d.DealTypeID, dt.Name, dt.RequiresRenewalSource,
    d.CompanyID, d.Company, d.PipelineID, d.Pipeline
ORDER BY
    WonAmount DESC;
';
  p_TechnicalDescription_54e751c846df := 'Grain: Deal. RequiresRenewalSource is the one flag this branches on, and it is the same flag CloseDealOperation uses to route a renewal — so the mix and the routing agree by construction. RenewalsMissingSource surfaces renewal-type deals with no RenewsContractID, which means the routing had nothing to renew against. Dates: actual close for closed deals, expected for open, reported in separate columns so the two are never added. Open deals in pipelines with IncludeInForecast = 0 are left out, as in Pipeline Summary; their won and lost deals stay, and naming the pipeline in PipelineID includes it.';
  p_Status_54e751c846df := 'Approved';
  p_QualityRank_54e751c846df := 7;
  p_ExecutionCostRank_54e751c846df := 2;
  p_UsesTemplate_54e751c846df := TRUE;
  p_AuditQueryRuns_54e751c846df := FALSE;
  p_CacheEnabled_54e751c846df := FALSE;
  p_EmbeddingVector_54e751c846df := '[-0.01614157296717167,0.05091577768325806,0.00389109761454165,-0.007861652411520481,0.023395268246531487,-0.010018768720328808,0.008366463705897331,-0.014441194012761116,-0.06342119723558426,-0.017384830862283707,0.017019471153616905,0.023663461208343506,0.0051657878793776035,0.10364948958158493,0.007602750789374113,-0.02212856151163578,0.008993245661258698,-0.02698063850402832,-0.01234792172908783,0.007042086683213711,0.036961667239665985,0.013886253349483013,-0.05184131860733032,-0.020275844261050224,-0.06775766611099243,0.022296611219644547,-0.01381156500428915,-0.013905680738389492,0.004366948269307613,-0.06468304991722107,0.026556359604001045,0.0037393358070403337,0.045613426715135574,-0.0020018157083541155,0.000002179822786274599,-0.023348841816186905,-0.032672982662916183,-0.020584711804986,-0.00820014625787735,0.035906579345464706,0.05509496107697487,-0.03512190282344818,0.008836420252919197,0.03696395829319954,0.014485986903309822,-0.025906946510076523,-0.013623775914311409,0.0562349408864975,-0.026440318673849106,0.01663830503821373,-0.0016694922233000398,-0.008013100363314152,-0.0712975561618805,-0.040711063891649246,0.008745591156184673,-0.02697848342359066,0.00455712852999568,-0.0747540071606636,0.007664953358471394,-0.07327704131603241,-0.045324306935071945,0.03276277333498001,0.018445389345288277,-0.028515039011836052,0.05827720835804939,0.062490757554769516,-0.038157254457473755,-0.0006236994522623718,-0.03435654938220978,-0.03854964300990105,0.08167964220046997,0.04526588320732117,0.0009688475984148681,-0.06669870764017105,-0.026653222739696503,-0.034236859530210495,-0.059398043900728226,0.004807651042938232,0.00960685033351183,-0.005703580100089312,-0.10797621309757233,0.014949939213693142,0.005923589691519737,-0.005276708863675594,-0.02978837676346302,-0.005082222167402506,0.00848272442817688,0.024928702041506767,-0.02977823093533516,-0.00548509182408452,0.07169625163078308,-0.007943174801766872,-0.018080776557